import {TOWN_RECIPES,townObjective,residents,citizenHome,waterAvailable} from './town.js?v=0.13.3';
import {ROOMS,sceneOf} from './indoors.js?v=0.13.3';
import {REGIONS,nextExit,regionOf} from './regions.js?v=0.13.3';
import {itemArt} from './item-art.js?v=0.13.3';

export function createTownUI({getState,world,run,openModal,closeModal,button,showLucy,showJournal,mark,ITEMS,neighborPerson,hillBoard,archiveBoard,hillRecipes}){
 const s=getState,f=()=>s().town.flags,actions=x=>`<div class="action-list">${x}</div>`;
 const panel=(title,body,kind='town')=>openModal(kind,'',title,body);
 function repair(key,then){const r=TOWN_RECIPES[key],missing=Object.entries(r.need).filter(([k,n])=>s().inventory[k]<n).map(([k,n])=>`${ITEMS[k].name} ${n-s().inventory[k]}`).join('、');return `<div class="recipe-card"><h3>${r.name}</h3><p>${Object.entries(r.need).map(([k,n])=>`${ITEMS[k].name} ${s().inventory[k]}/${n}`).join(' · ')}</p>${actions(button(r.name,()=>{if(run('townRepair',{key}))then();},{primary:true,disabled:missing?'还缺'+missing:s().energy<r.energy?'体力不足':'',small:`体力 ${r.energy} · ${r.minutes}分钟`}))}</div>`;}
 function board(){panel('广场上的来信',()=>{
  const ready=s().expansion.flags.posted;
  return `<p>${!f().started?ready?'露西把一把旧钥匙夹在信里：“磨坊转了，信也送到了。我们是不是能把会馆重新打开？”':'告示板上还留着旧夜市的照片。先恢复磨坊与邮路；等来信能够送达，会馆的钥匙就会到你手中。':f().market?'钟声过后，告示板上终于贴了新的日期。街坊每天留一份简单委托，没有截止时间。':'路牌、会馆、果园和三位熟人的邀请，正一点点把小镇重新接起来。'}</p>${!f().started?actions(button('接过会馆钥匙',()=>{if(run('townStart')){mark();board();}},{primary:true,disabled:ready?'':'完成第二章邮路后开放'})):!f().sign?repair('sign',board):'<p>✓ 广场路牌已修好</p>'}${f().market?actions(button('封存库的回声 · 巡查清单',archiveBoard,{small:s().water.reported?'水源报告后的可选后续':'先交回水源调查报告'})+button('山坡温室的来信与新委托',hillBoard,{primary:true})+button('交付街坊果篮 · 苹果2个',()=>{if(run('townOrder'))board();},{disabled:s().town.orderDay===s().day?'今天已完成':s().inventory.apple<2?'还缺苹果':'',small:'20金币 · 每天一次'}))+'<p class="small-note">'+(waterAvailable(s())?'露西的调查来信已经到了。去找她，可自愿接取水源调查。':'今晚先享受夜市。明早会有露西的新来信。')+'</p>':''}${actions(button('查看生活主线与村民去向',()=>showJournal('town'))+button('继续逛逛',closeModal))}`;
 });}
 function hall(){panel('小镇会馆',()=>`<p>${f().hall?'门轴重新上了油，屋里有人留下了干净的抹布。厨房、旧名册和照片各在一侧，中间留给大家走动。':'屋顶漏过雨，门轴也松了。可以先进屋看看，修复后再整理名册与果园。'}</p>${f().started&&!f().hall&&f().sign?repair('hall',hall):''}${actions(button('进入会馆',()=>{if(run('enterRoom',{room:'hall'}))closeModal();},{primary:true})+(!f().started?button('先去告示板看看',()=>{closeModal();world.go(REGIONS.town.spots.find(p=>p.id==='townBoard'));}):'')+button('暂时留在广场',closeModal))}`);}
 function person(id){const person=residents(s()).find(p=>p.id===id);if(!person||!run('townTalk',{person:id}))return;const quotes={taoen:s().water.reported?'我现在每天都去检查北闸。放心，果园这边是干净的蓄水。':f().firstHarvest?'看见苹果了吗？老树不是忘了结果，只是一直没人替它把水接回来。':'我每天早上先去果园。北闸维修册缺了一页，不过这边的水槽，只需要你肯动手。',mila:s().water.reported?'那盏灯我记得。今天先不说水渠，来帮我挑一块桌布。':f().hall?'会馆的窗子擦亮了，旧照片里那些人也像醒过来一样。':'这些桌布我洗了好几次。总觉得有一天，小镇会重新用上。',lucy:f().market?'炉火和夜市都亮了。今天的面包还热着。':'你们把摊子支好，我把最热的面包留到晚上。'};
  panel(person.name+' · '+person.role,()=>`<div class="town-conversation"><span class="town-person ${id}" aria-hidden="true"></span><p class="quote">“${quotes[id]}”</p></div>${actions((f().letters&&!s().town.invites[id]?button('递交夜市邀请',()=>{if(run('townInvite',{person:id}))personMenu(id);},{primary:true}):s().town.invites[id]?'<p>✓ 已经约好夜市见面</p>':'')+(f().market?button('聊聊你的故事',()=>neighborPerson(id)):'')+(id==='lucy'?button('买卖、晚餐与露西的其他话',showLucy):'')+button('查看大家现在在哪',()=>showJournal('town'))+button('回头见',closeModal))}`,'townTalk');
 }
 const personMenu=id=>person(id);
 function letters(){panel('三封邀请，各有去处',()=>`<p>旧名册写着：露西是面包师，陶恩是取水工，米菈是洗衣人。为他们对应一份擅长的准备工作。</p>${!f().letters?`<div class="town-letter-grid">${[['lucy','露西'],['taoen','陶恩'],['mila','米菈']].map(([id,name])=>`<label>${name}<select id="invite-${id}"><option value="">选择准备工作</option><option value="bread">烤好面包</option><option value="water">检查水槽</option><option value="cloth">整理桌布</option></select></label>`).join('')}</div>${actions(button('把三封邀请整理好',()=>{const payload=Object.fromEntries(['lucy','taoen','mila'].map(id=>[id,document.querySelector('#invite-'+id).value]));if(run('townLetters',payload))letters();},{primary:true,disabled:!f().hall?'先到门外修复会馆':''}))}`:`<p>✓ 名册已经理好。请把邀请递给露西、陶恩和米菈。</p>${!citizenHome(s())?'<p>两位村民还在调查途中。露西代收他们的邀请；果园工作可照着留下的图纸继续，不必等战斗结束。</p>':''}${actions(button('查看村民现在的位置',()=>showJournal('town'),{primary:true}))}`}${actions(button('先放下名册',closeModal))}`);}
 function trees(){const t=s().town;panel('老果树记得结果',()=>`<p>${!f().cleared?'先把树下的杂草清掉，让旧根透透气。':!f().irrigation?'草已经清好了，左上角的蓄水槽还需要木材、石料和松脂。':t.growth===2?'叶子间已经挂满苹果。每次可以固定收获4个。':`果树已经度过 ${t.growth}/2 个有照料的夜晚。${t.tended||s().weather==='rain'?'今天已经喝饱水，回家过夜就会生长。':'浇一次水，再回家睡觉。'}`}</p>${actions(!f().cleared?button('清理树下杂草',()=>{if(run('townClear'))trees();},{primary:true,disabled:!f().hall?'先修复会馆并领取工具':s().energy<5?'体力不足':''}):!f().irrigation?button('走到蓄水槽',()=>{closeModal();world.go(REGIONS.orchard.spots.find(p=>p.id==='basin'));},{primary:true}):t.growth===2?button('采收苹果 ×4',()=>{if(run('townHarvest'))trees();},{primary:true}):button('给果树浇水',()=>{if(run('townTend'))trees();},{primary:true,disabled:t.tended||s().weather==='rain'?'今日已照料':s().energy<3?'体力不足':''}))+actions(button('继续在果园走走',closeModal))}<p class="small-note">雨天自动照料；漏浇水只暂停，不会枯死。成熟后不会腐坏。</p>`);}
 function basin(){panel('把水接回果园',()=>`<p>${f().irrigation?'槽里的水清亮了。雨天也会替你照料果树。':'陶恩留下了简单的修复图：换木板、垫石块，再用松脂补上接缝。'}</p>${!f().irrigation&&f().cleared?repair('irrigation',basin):!f().cleared?'<p>先到果树旁清理杂草。</p>':'<p>✓ 蓄水槽已修复</p>'}${actions(button('回到果树旁',()=>{closeModal();world.go(REGIONS.orchard.spots.find(p=>p.id==='orchardTrees'));},{primary:true}))}`);}
 function stall(){panel('今晚，给谁留一份？',()=>`<p>把面包与果篮排成你喜欢的样子，再准备两份热食。已交付的食物会妥善保存。</p><p>当前布置：${s().town.layout? s().town.layout==='west'?'面包迎客，果篮靠钟':'果篮迎客，面包靠钟':'尚未安排'}</p>${actions(!f().market?button('面包迎客，果篮靠钟',()=>{if(run('townLayout',{layout:'west'}))stall();},{disabled:!f().hall?'先修复会馆':''})+button('果篮迎客，面包靠钟',()=>{if(run('townLayout',{layout:'east'}))stall();},{disabled:!f().hall?'先修复会馆':''}):'')}<p>随身南瓜派 ${s().inventory.pie} · 香草鱼汤 ${s().inventory.fishSoup}</p>${f().food?'<p>✓ 两份热食已备好</p>':actions([2,1,0].map(pie=>button(pie===2?'交付两份南瓜派':pie===0?'交付两份香草鱼汤':'交付南瓜派与鱼汤各一份',()=>{if(run('townFood',{pie}))stall();},{disabled:!f().firstHarvest?'先收获第一筐苹果':s().inventory.pie<pie||s().inventory.fishSoup<2-pie?'食物还不够':''})).join(''))}${actions(button('查看夜市筹备进度',()=>showJournal('town'))+button('继续逛逛',closeModal))}`);}
 function bell(){panel('让钟声替大家开门',()=>`<p>${f().market?'夜市已经开张，灯下总有一个可以停留的位置。':'不必赶在某一天完成。会馆、三封邀请、果园、摊位和两份热食都备好后，18:00以后敲响钟。'}</p>${actions(f().market?button('重温夜市开幕',()=>finale(0),{primary:true}):button('敲响开市钟',()=>{if(run('townOpen')){mark();finale(0);}},{primary:true,disabled:s().minute<1080?'18:00后再来':!f().food||!s().town.layout||!Object.values(s().town.invites).every(Boolean)?'先完成手记中的筹备':''}))+actions(button('查看生活主线',()=>showJournal('town'))+button('继续生活',closeModal))}`);}
 function finale(i){const parts=[['第一盏灯 · 炉火',s().flags.departed?'露西把第一块面包放在磨坊旧木牌旁：“爷爷，今天糖放得刚好。”磨轮在远处轻轻转着。':'露西举起面包。奥伦在灯边假装挑剔：“这次，勉强比我的好一点。”她笑着又给他留了一个位置。'],['第二盏灯 · 回来的路',s().expansion.flags.veraDeparted?'有人把铜燕子扣针挂在邮袋边。写给送信人的邀请，被郑重放在空椅上。':'薇拉终于不用赶路。她把邮袋放下，收到的第一封邀请就放在最上面。'],['第三盏灯 · 小镇再次开门',citizenHome(s())?'陶恩搬来果篮，米菈铺开一直收好的桌布。钟响时，你发现大家已经开始谈明天的事了。':'露西照着陶恩的图纸摆好果篮，铺上米菈留下的桌布。两张椅子被留了出来，小镇会一直等他们回来。']];panel(parts[i][0],()=>`<p class="quote">${parts[i][1]}</p><p class="small-note">${i===2?'第一部生活主线完成 · 果园、会馆厨房和街坊委托已开放。水源调查明天来信，可自愿接取。':`${i+1} / 3 · 灯下的片刻`}</p>${actions(button(i<2?'听听下一段':'回到灯下，继续生活',()=>i<2?finale(i+1):closeModal(),{primary:true}))}`,'townTalk');}
 function kitchen(){panel('会馆厨房 · 苹果蜜酱',()=>`${itemArt('jam')}<p>果园苹果2个、蜂蜜1份，体力3，15分钟。使用随身食材；制作后可出售。</p><p>苹果 ${s().inventory.apple}/2 · 蜂蜜 ${s().inventory.honey}/1</p>${actions(button('熬一罐苹果蜜酱',()=>{if(run('townCook'))kitchen();},{primary:true,disabled:!f().market?'夜市开幕后开放':s().inventory.apple<2||s().inventory.honey<1?'食材不足':s().energy<3?'体力不足':''})+(s().neighborhood.lucy===3?button('烤苹果小酥饼',()=>{if(run('bakePastry'))kitchen();},{small:'苹果1 · 面粉1 · 蜂蜜1 · 体力4 · 20分钟',disabled:s().inventory.apple<1||s().inventory.flour<1||s().inventory.honey<1?'食材不足':s().energy<4?'体力不足':''}):'')+button('离开厨房',closeModal))}${hillRecipes?.(kitchen)||''}`);}
 function goResident(p){closeModal();const here=sceneOf(s());if(here===p.scene){const target=world.spots().find(t=>t.id===p.spotId);if(target)world.go(target);return;}if(s().life.room){world.go(ROOMS[here].spots[0]);return;}const targetRegion=ROOMS[p.scene]?.parent||p.scene;if(regionOf(s())!==targetRegion){world.go(nextExit(regionOf(s()),targetRegion));return;}world.go(world.spots().find(q=>q.id===({shop:'lucy',hall:'hallDoor',repair:'repairDoor',laundry:'laundryDoor'})[p.scene]));}
 function journalHTML(){const q=townObjective(s()),t=s().town;return `<div class="current-wish"><h3>${q.title}</h3><p>${q.body}</p><ul>${q.checks.map(([text,done])=>`<li class="${done?'done':''}">${done?'✓':'□'} ${text}</li>`).join('')}</ul></div><div class="town-progress">${[['修好广场路牌',f().sign],['修复会馆',f().hall],['整理并送达邀请',f().letters&&Object.values(t.invites).every(Boolean)],['恢复果园、首次采收',f().firstHarvest],['安排摊位与两份热食',!!t.layout&&f().food],['公共夜市开幕',f().market]].map(([name,done])=>`<p>${done?'✓':'□'} ${name}</p>`).join('')}</div><h3>街坊现在在哪</h3><p class="small-note">夜市后按作息步行往返；雨天改在屋内工作。晚间18:00–20:00会馆见，之后回家。</p>${residents(s()).map(p=>`<div class="town-resident"><span><strong>${p.name}</strong> · ${ROOMS[p.scene]?.name||REGIONS[p.scene].name}${p.moving?' · 正在去'+p.destination:p.working?' · 工作中':''}</span>${button('去找'+p.name,()=>goResident(p))}</div>`).join('')}${!citizenHome(s())?'<p>陶恩和米菈目前在水渠调查中。会馆保留他们的工具、桌布和委托，不影响生活主线。</p>':''}${actions(button('追踪生活主线',()=>{mark();closeModal();},{primary:true}))}`;}
 function handle(target){
  const personId={townLucy:'lucy',townTaoen:'taoen',townMila:'mila'}[target.id];if(personId){person(personId);return true;}
  const handlers={townBoard:board,hallDoor:hall,hallRegister:letters,orchardTrees:trees,basin,marketStall:stall,marketBell:bell,hallKitchen:kitchen,hallPhotos:()=>panel('照片里，也有今天',()=>`<p>${s().flags.departed?'奥伦留下了磨轮和手艺。':'磨坊照片里，奥伦正假装没有偷吃南瓜派。'}${s().expansion.flags.veraDeparted?'薇拉的扣针旁多了一张新的夜市照片。':'薇拉说，等下次拍照，她一定赶得上。'}</p>${actions((f().market?button('翻到夜市开幕那一页',()=>finale(0)):'')+button('翻开人物故事',()=>showJournal('people'))+button('合上相册',closeModal))}`),orchardBench:()=>panel('树叶响的时候',()=>`<p>坐一会儿，日子不用赶。</p>${actions(button('坐到傍晚',()=>{if(run('wait'))closeModal();},{disabled:s().minute>=1080?'已经入夜':''})+button('继续散步',closeModal))}`)};
  if(handlers[target.id]){handlers[target.id]();return true;}return false;
 }
 return {handle,journalHTML,person};
}
